package dk.jamesbabz.madkursus.outbound.recipe;
import dk.jamesbabz.madkursus.outbound.recipe.details.*; import dk.jamesbabz.madkursus.service.models.RecipeCookHistory; import dk.jamesbabz.madkursus.service.ports.RecipeCookHistoryPort; import jakarta.persistence.EntityManager; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class RecipeCookHistoryAdapterImpl implements RecipeCookHistoryPort { private final RecipeCookHistoryJpaRepository repository; private final EntityManager entityManager; public RecipeCookHistory save(RecipeCookHistory h){var e=repository.save(new RecipeCookHistoryEntity(h.id(),h.userId(),entityManager.getReference(RecipeEntity.class,h.recipeId()),h.recipeName(),h.portions(),h.cookedAt()));return new RecipeCookHistory(e.getId(),e.getUserId(),e.getRecipe()==null?null:e.getRecipe().getId(),e.getRecipeName(),e.getPortions(),e.getCookedAt());} }
